1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #14161c;
16	    color: #e8e8ec;
17	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
18	  }
19	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
20	  .board {
21	    display: grid;
22	    grid-template-columns: repeat(10, 28px);
23	    grid-template-rows: repeat(20, 28px);
24	    gap: 1px;
25	    padding: 1px;
26	    background: #2a2d36;
27	    border: 2px solid #3a3e4a;
28	  }
29	  .cell { width: 28px; height: 28px; background: #0d0e12; }
30	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
31	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
32	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
33	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
34	  .preview {
35	    display: grid;
36	    grid-template-columns: repeat(4, 16px);
37	    grid-template-rows: repeat(2, 16px);
38	    gap: 1px;
39	    margin-top: 8px;
40	  }
41	  .preview .mini { width: 16px; height: 16px; background: transparent; }
42	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
43	  button {
44	    font: inherit;
45	    background: #2f333d;
46	    color: #e8e8ec;
47	    border: 1px solid #454a57;
48	    padding: 6px 10px;
49	    cursor: pointer;
50	  }
51	  button:hover { background: #3a3e4a; }
52	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
53	
54	  /* Piece colours, shared by the board and the preview. */
55	  [data-piece="I"] { background: #22c5e6 !important; }
56	  [data-piece="O"] { background: #f2d024 !important; }
57	  [data-piece="T"] { background: #a64ee6 !important; }
58	  [data-piece="S"] { background: #3fcf5a !important; }
59	  [data-piece="Z"] { background: #e8423f !important; }
60	  [data-piece="J"] { background: #3563e9 !important; }
61	  [data-piece="L"] { background: #f08a24 !important; }
62	</style>
63	</head>
64	<body>
65	<div class="game">
66	  <div class="board" data-testid="board" id="board"></div>
67	  <div class="side">
68	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
69	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
70	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
71	    <div class="panel"><div class="label">Next</div><div class="preview" id="preview"></div></div>
72	    <div class="status" id="status"></div>
73	    <button type="button" id="restart">New game</button>
74	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
75	  </div>
76	</div>
77	<script>
78	(function () {
79	  "use strict";
80	
81	  var ROWS = 20;
82	  var COLS = 10;
83	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
84	  var MIN_UPCOMING = 5;
85	
86	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
87	  var SHAPES = {
88	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
89	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
90	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
91	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
92	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
93	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
94	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
95	  };
96	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
97	  // Size of the square box each piece rotates inside.
98	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
99	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
100	  var KICKS = [0, -1, 1, -2, 2];
101	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
102	  var LOCK_TICKS = 2;
103	  var MAX_LOCK_RESETS = 3;
104	  // Scoring (decision): points by rows cleared at once, times level. Clearing rows together
105	  // must always beat clearing the same rows in smaller groups. Soft drop 1/cell, hard drop 2/cell.
106	  var LINE_SCORES = [0, 100, 300, 500, 800];
107	  var SOFT_DROP_POINTS = 1;
108	  var HARD_DROP_POINTS = 2;
109	
110	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
111	  var board;
112	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
113	  var upcoming;  // array of piece letters, soonest first
114	  var score, level, lines, status;
115	  var timer = null;
116	
117	  var boardEl = document.getElementById("board");
118	  var previewEl = document.getElementById("preview");
119	  var scoreEl = document.getElementById("score");
120	  var levelEl = document.getElementById("level");
121	  var linesEl = document.getElementById("lines");
122	  var statusEl = document.getElementById("status");
123	  var cellEls = [];
124	  var previewEls = [];
125	
126	  // [REQ-001] Build the 200 board cells and the preview cells once.
127	  function buildDom() {
128	    for (var r = 0; r < ROWS; r++) {
129	      cellEls.push([]);
130	      for (var c = 0; c < COLS; c++) {
131	        var el = document.createElement("div");
132	        el.className = "cell";
133	        el.setAttribute("data-testid", "cell");
134	        el.setAttribute("data-row", String(r));
135	        el.setAttribute("data-col", String(c));
136	        el.setAttribute("data-filled", "false");
137	        el.setAttribute("data-piece", "");
138	        boardEl.appendChild(el);
139	        cellEls[r].push(el);
140	      }
141	    }
142	    for (var i = 0; i < 8; i++) {
143	      var m = document.createElement("div");
144	      m.className = "mini";
145	      m.setAttribute("data-piece", "");
146	      previewEl.appendChild(m);
147	      previewEls.push(m);
148	    }
149	  }
150	
151	  function emptyBoard() {
152	    var b = [];
153	    for (var r = 0; r < ROWS; r++) {
154	      var row = [];
155	      for (var c = 0; c < COLS; c++) row.push(null);
156	      b.push(row);
157	    }
158	    return b;
159	  }
160	
161	  function isType(t) { return TYPES.indexOf(t) !== -1; }
162	
163	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
164	  function randomBag() {
165	    var bag = TYPES.slice();
166	    for (var i = bag.length - 1; i > 0; i--) {
167	      var j = Math.floor(Math.random() * (i + 1));
168	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
169	    }
170	    return bag;
171	  }
172	
173	  function fillUpcoming() {
174	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
175	  }
176	
177	  function cellsOf(piece, row, col) {
178	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
179	  }
180	
181	  function fits(piece, row, col) {
182	    var cells = cellsOf(piece, row, col);
183	    for (var i = 0; i < cells.length; i++) {
184	      var r = cells[i][0], c = cells[i][1];
185	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
186	      if (board[r][c]) return false;
187	    }
188	    return true;
189	  }
190	
191	  // [REQ-001] Take the next piece from the queue and place it at the top.
192	  function spawn() {
193	    fillUpcoming();
194	    var type = upcoming.shift();
195	    fillUpcoming();
196	    var piece = {
197	      type: type,
198	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
199	      row: 0,
200	      col: SPAWN_COL[type],
201	      lockTicks: 0,
202	      lockResets: 0
203	    };
204	    if (!fits(piece, piece.row, piece.col)) {
205	      current = null;
206	      status = "over";
207	      stopTimer();
208	      return;
209	    }
210	    current = piece;
211	  }
212	
213	  // [REQ-003] Remove full rows, drop the rows above, add rows to lines and score at the current level.
214	  function clearLines() {
215	    var kept = board.filter(function (row) {
216	      return row.some(function (v) { return !v; });
217	    });
218	    var cleared = ROWS - kept.length;
219	    while (kept.length < ROWS) {
220	      var empty = [];
221	      for (var c = 0; c < COLS; c++) empty.push(null);
222	      kept.unshift(empty);
223	    }
224	    board = kept;
225	    if (cleared > 0) {
226	      score += LINE_SCORES[cleared] * level;
227	      lines += cleared;
228	      var newLevel = Math.floor(lines / 10) + 1;
229	      if (newLevel !== level) {
230	        level = newLevel;
231	        if (status === "running") startTimer();
232	      }
233	    }
234	  }
235	
236	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
237	  function lockPiece() {
238	    cellsOf(current, current.row, current.col).forEach(function (rc) {
239	      board[rc[0]][rc[1]] = current.type;
240	    });
241	    current = null;
242	    clearLines();
243	    spawn();
244	  }
245	
246	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
247	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
248	  function gravityStep() {
249	    if (status !== "running" || !current) return;
250	    if (fits(current, current.row + 1, current.col)) {
251	      current.row += 1;
252	      current.lockTicks = 0;
253	    } else {
254	      current.lockTicks += 1;
255	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
256	    }
257	  }
258	
259	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay, at most 3 times per piece.
260	  function shift(dx) {
261	    if (!fits(current, current.row, current.col + dx)) return;
262	    var resting = !fits(current, current.row + 1, current.col);
263	    current.col += dx;
264	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
265	      current.lockResets += 1;
266	      current.lockTicks = 0;
267	    }
268	  }
269	
270	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
271	  function rotateCW() {
272	    var n = BOX[current.type];
273	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
274	    for (var i = 0; i < KICKS.length; i++) {
275	      if (fits(rotated, current.row, current.col + KICKS[i])) {
276	        current.cells = rotated.cells;
277	        current.col += KICKS[i];
278	        return;
279	      }
280	    }
281	  }
282	
283	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW.
284	  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
285	  function doInput(action) {
286	    if (status !== "running" || !current) return;
287	    if (action === "left") {
288	      shift(-1);
289	    } else if (action === "right") {
290	      shift(1);
291	    } else if (action === "rotateCW") {
292	      rotateCW();
293	    } else if (action === "softDrop") {
294	      if (fits(current, current.row + 1, current.col)) {
295	        current.row += 1;
296	        score += SOFT_DROP_POINTS;
297	      }
298	    } else if (action === "hardDrop") {
299	      while (fits(current, current.row + 1, current.col)) {
300	        current.row += 1;
301	        score += HARD_DROP_POINTS;
302	      }
303	      lockPiece();
304	    }
305	  }
306	
307	  function gravityInterval() {
308	    return Math.max(100, 1000 - (level - 1) * 90);
309	  }
310	
311	  function stopTimer() {
312	    if (timer !== null) { clearInterval(timer); timer = null; }
313	  }
314	
315	  function startTimer() {
316	    stopTimer();
317	    timer = setInterval(function () {
318	      gravityStep();
319	      render();
320	    }, gravityInterval());
321	  }
322	
323	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
324	  function render() {
325	    var drawn = board.map(function (row) { return row.slice(); });
326	    if (current) {
327	      cellsOf(current, current.row, current.col).forEach(function (rc) {
328	        drawn[rc[0]][rc[1]] = current.type;
329	      });
330	    }
331	    for (var r = 0; r < ROWS; r++) {
332	      for (var c = 0; c < COLS; c++) {
333	        var v = drawn[r][c] || "";
334	        var el = cellEls[r][c];
335	        if (el.getAttribute("data-piece") !== v) {
336	          el.setAttribute("data-piece", v);
337	          el.setAttribute("data-filled", v ? "true" : "false");
338	        }
339	      }
340	    }
341	    previewEls.forEach(function (m) { m.setAttribute("data-piece", ""); });
342	    var nextType = upcoming[0];
343	    if (nextType) {
344	      SHAPES[nextType].forEach(function (o) {
345	        previewEls[o[0] * 4 + o[1]].setAttribute("data-piece", nextType);
346	      });
347	    }
348	    scoreEl.textContent = String(score);
349	    levelEl.textContent = String(level);
350	    linesEl.textContent = String(lines);
351	    statusEl.textContent = status === "over" ? "Game over" : "";
352	  }
353	
354	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
355	  function newGame(queue) {
356	    board = emptyBoard();
357	    score = 0;
358	    level = 1;
359	    lines = 0;
360	    status = "running";
361	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
362	    current = null;
363	    spawn();
364	    if (status === "running") startTimer();
365	    render();
366	  }
367	
368	  window.__tetris = {
369	    newGame: function (queue) { newGame(queue); },
370	
371	    setQueue: function (queue) {
372	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
373	      fillUpcoming();
374	      render();
375	    },
376	
377	    setBoard: function (rows) {
378	      var b = emptyBoard();
379	      for (var r = 0; r < ROWS; r++) {
380	        var line = (rows && rows[r]) || "";
381	        for (var c = 0; c < COLS; c++) {
382	          var ch = line.charAt(c);
383	          b[r][c] = isType(ch) ? ch : null;
384	        }
385	      }
386	      board = b;
387	      render();
388	    },
389	
390	    tick: function (n) {
391	      if (n === undefined) n = 1;
392	      for (var i = 0; i < n; i++) gravityStep();
393	      if (status === "running") startTimer();
394	      render();
395	    },
396	
397	    input: function (action) {
398	      doInput(action);
399	      render();
400	    },
401	
402	    getBoard: function () {
403	      return board.map(function (row) {
404	        return row.map(function (v) { return v || "."; }).join("");
405	      });
406	    },
407	
408	    getState: function () {
409	      return {
410	        current: current
411	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
412	          : null,
413	        next: upcoming.slice(),
414	        score: score,
415	        level: level,
416	        lines: lines,
417	        status: status
418	      };
419	    }
420	  };
421	
422	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
423	
424	  document.addEventListener("keydown", function (e) {
425	    var action = KEYS[e.key];
426	    if (!action) return;
427	    e.preventDefault();
428	    window.__tetris.input(action);
429	  });
430	
431	  document.getElementById("restart").addEventListener("click", function (e) {
432	    e.currentTarget.blur();
433	    newGame();
434	  });
435	
436	  buildDom();
437	  newGame();
438	})();
439	</script>
440	</body>
441	</html>
442

