p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  .preview {
    display: grid;''','''  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
  .next-item[data-piece] { background: transparent !important; }
