rep('''  var MIN_UPCOMING = 5;''','''  var MIN_UPCOMING = 5;
  var PREVIEW_COUNT = 3;''')
rep('''  var previewEls = [];''','''  var previewItems = [];  // { el, minis } per upcoming piece shown, soonest first''')
rep('''  // [REQ-001] Build the 200 board cells and the preview cells once.''','''  // [REQ-001] Build the 200 board cells and the preview cells once.
