rep('''    for (var i = 0; i < 8; i++) {
      var m = document.createElement("div");
      m.className = "mini";
      m.setAttribute("data-piece", "");
      previewEl.appendChild(m);
      previewEls.push(m);
    }''','''    for (var i = 0; i < PREVIEW_COUNT; i++) {
      var item = document.createElement("div");
      item.className = "preview next-item";
      item.setAttribute("data-testid", "next-piece-item");
      item.setAttribute("data-piece", "");
      var minis = [];
      for (var k = 0; k < 8; k++) {
        var m = document.createElement("div");
        m.className = "mini";
        m.setAttribute("data-piece", "");
        item.appendChild(m);
        minis.push(m);
      }
      previewEl.appendChild(item);
      previewItems.push({ el: item, minis: minis });
    }''')
rep('''  // [REQ-001] Take the next piece from the queue and place it at the top.''','''  // [REQ-001] Take the next piece from the queue and place it at the top.
  // [REQ-004] If the new piece does not fit where it spawns, the game is over.''')
rep('''      status = "over";''','''      status = "gameover";''')
rep('''    previewEls.forEach(function (m) { m.setAttribute("data-piece", ""); });
    var nextType = upcoming[0];
    if (nextType) {
      SHAPES[nextType].forEach(function (o) {
        previewEls[o[0] * 4 + o[1]].setAttribute("data-piece", nextType);
      });
    }''','''    // [REQ-004] Next three pieces, soonest first, each in its board colour.
    previewItems.forEach(function (item, i) {
      var type = upcoming[i] || "";
      item.el.setAttribute("data-piece", type);
      item.el.hidden = !type;
      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
      if (type) {
        SHAPES[type].forEach(function (o) {
          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
        });
      }
    });''')
rep('''    statusEl.textContent = status === "over" ? "Game over" : "";''','''    statusEl.hidden = status !== "gameover";''')
open(p,'w').write(s)
EOF
